"""
Web-App-Manifest + Icon-Ausspielung fuer die PWA-Installierbarkeit der
Oberflaeche.

Ausgeliefert von server.py unter /manifest.json (+ /icon-192.png,
/icon-512.png, /apple-touch-icon.png). Ermoeglicht "Installieren"
(Chrome/Edge) bzw. "Zum Dock hinzufuegen" (Safari), damit die Oberflaeche in
einem eigenen Fenster ohne Tabs/Adresszeile laeuft statt in einem
Browser-Tab -- weder die gebaute .app (macapp.py ist reine Lifecycle-Huelle
ohne eigenes Fenster) noch ./run.command serve bieten das von sich aus.

Icons haengen als ECHTE Datei-Routen im Manifest (/icon-192.png, ...), NICHT
als data:-URI direkt im JSON -- Safaris "Zum Dock hinzufuegen" ignoriert
data:-URI-Icons in Manifest UND apple-touch-icon nachweislich unzuverlaessig
und faellt sonst auf ein generisches Buchstaben-Icon zurueck (siehe
technische_funktionen.md, PWA-Abschnitt). apple-touch-icon.png steht
zusaetzlich bereit, weil es laut Apple-Dokumentation Vorrang vor den
Manifest-Icons hat.

Die drei Base64-Konstanten sind PNGs, generiert aus der gepolsterten
App-Icon-Zeichnung (nicht der randlosen Favicon-Fassung) von
build_assets/make_icon.py::patch_pwa_module() -- build_assets/ selbst ist im
gebuendelten Bundle zur Laufzeit nicht verfuegbar, siehe config.bundle_dir().
Nach einem Lauf von make_icon.py reicht ein Serverneustart, anders als bei
den Favicons braucht es KEIN './run.command report' (Manifest + Icons werden
live aus diesem Modul erzeugt, nie in report.html eingebacken).

start_url/scope sind bewusst relativ ("/"): das Manifest wird vom selben
Prozess ausgeliefert, den der Browser gerade anspricht, damit loest eine
relative Angabe unabhaengig vom konfigurierten Port (--port, Default 8756)
automatisch richtig auf.

name/short_name sind wie <title>TrackTab</title> (index.html) und
CFBundleDisplayName (tracktab.spec) ein fixer Produktname -- OS-Chrome
(Dock-Tooltip, Installations-Dialog), nicht Teil der DOM-i18n-Mechanik
(t()/data-i18n) und in beiden Sprachen identisch.
"""
from __future__ import annotations

import base64
import json

# Von build_assets/make_icon.py::patch_pwa_module() ersetzt -- reines Base64
# ohne "data:image/png;base64,"-Praefix (anders als die Favicon-data:URIs in
# index.html werden diese drei als echte Bilddateien ausgeliefert, siehe
# server.py._get_icon()). Platzhalter hier sind winzige, aber gueltige
# 1x1-PNGs, damit Manifest/Icons auch ohne einen vorherigen
# make_icon.py-Lauf gueltig bleiben.
_ICON_192_B64 = ""
_ICON_512_B64 = ""
_ICON_APPLE_TOUCH_B64 = ""

# Rohe PNG-Bytes, einmal beim Import dekodiert -- server.py sendet diese
# unveraendert unter /icon-192.png, /icon-512.png, /apple-touch-icon.png.
ICON_192_PNG: bytes = base64.b64decode(_ICON_192_B64)
ICON_512_PNG: bytes = base64.b64decode(_ICON_512_B64)
ICON_APPLE_TOUCH_PNG: bytes = base64.b64decode(_ICON_APPLE_TOUCH_B64)

# Gleicher Farbton wie BG_TOP in build_assets/make_icon.py, fuer optische
# Naehe zum App-Icon in Installations-Dialog/Splash.
_THEME_COLOR = "#24293a"

_MANIFEST = {
    "name": "TrackTab",
    "short_name": "TrackTab",
    "description": "Analyse der Musikbibliothek auf Kompressionsartefakte",
    "start_url": "/",
    "scope": "/",
    "display": "standalone",
    "lang": "de",
    "theme_color": _THEME_COLOR,
    "background_color": _THEME_COLOR,
    "icons": [
        {"src": "/icon-192.png", "sizes": "192x192", "type": "image/png"},
        {"src": "/icon-512.png", "sizes": "512x512", "type": "image/png"},
    ],
}

# Einmal beim Import gebaut, nicht pro Anfrage -- server.py._get_manifest()
# sendet dies unveraendert.
MANIFEST_JSON: bytes = json.dumps(_MANIFEST, ensure_ascii=False).encode("utf-8")
